import{_ as a,o as e,c as d,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"三维装箱（BPP3D）：适用问题与学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp3d/index.md","filePath":"zh-cn/frameworks/bpp3d/index.md"}'),o={name:"zh-cn/frameworks/bpp3d/index.md"};function i(l,t,n,h,c,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="三维装箱-bpp3d-适用问题与学习路线" tabindex="-1">三维装箱（BPP3D）：适用问题与学习路线 <a class="header-anchor" href="#三维装箱-bpp3d-适用问题与学习路线" aria-label="Permalink to &quot;三维装箱（BPP3D）：适用问题与学习路线&quot;">​</a></h1><p>货物具有长宽高和重量，需要选择箱型、朝向和放置位置，最后得到可检查、可展示的装载方案。第一课只处理长方体，不从圆柱与复杂支撑开始。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>角色</th><th>核心字段</th></tr></thead><tbody><tr><td>货物与包装</td><td><code>Item</code> / <code>Package</code></td><td>输入</td><td>尺寸、重量、物料和允许朝向</td></tr><tr><td>箱型</td><td><code>BinType</code></td><td>输入</td><td>几何、承重和类型 ID</td></tr><tr><td>候选装载层</td><td><code>BinLayer</code></td><td>中间概念</td><td>箱型、需求覆盖与物品放置记录</td></tr><tr><td>应用服务</td><td><code>ColumnGenerationApplicationService</code></td><td>调用 / 校验入口</td><td>主问题、生成、最终选择与装载分析</td></tr><tr><td>最终结果校验</td><td><code>PackingGeometryGuard</code></td><td>调用 / 校验入口</td><td>越界、重叠和已支持形状的几何规则</td></tr><tr><td>最终装箱结果</td><td><code>PackingResult</code> / <code>packingSnapshot</code></td><td>输出</td><td>箱体实例、货物坐标、朝向、装载顺序</td></tr></tbody></table><p>候选列描述可选的装载结构，不是已经完成的最终装箱。优化选择、实际放置和报告都要接通。</p><p>箱型规定尺寸、承重等规格；箱体实例是具有独立 ID 的具体可用箱体。定义一种箱型，不等于可无限使用该规格的箱体。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Kotlin 与 Rust 的入口差异</p><p>Kotlin 通过应用请求、标准执行器和装箱结果分析器完成求解。Rust 支持转换后的领域输入和 CSV 输入，需要分别提供受限主问题与最终整数求解的执行器。请按各语言示例构造输入并配置后端。</p></div><p>先用固定箱型和少量初始候选层验证配置与调用，再引入自动候选、多箱型与目标配置。受限主问题只考虑已生成的候选层；常用算法名称见<a href="./../#terminology">术语说明</a>。</p><p>本课的应用服务已经包含列生成和最终整数求解，没有单独的 <code>Bpp3dMilp</code> 入口。小实例先固定带实际坐标的初始候选层与可用箱体；增加朝向和箱型后，再扩大候选数和迭代次数上限。具体字段与后端配置见<a href="./business-scenario.html#entry-budget">第二课</a>。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>圆柱支持取决于所选轴向，以及候选生成、支撑检查、最终结果校验是否支持该形状，不代表支持任意三维旋转。</li><li>装载率应使用对应形状的真实体积，不能把外接体积当实占体积。</li><li>框架提供用于展示的结果数据；可视化页面和渲染器仍需应用自行实现。</li><li><code>finalSolved</code>、实际装箱结果和定价诊断应一起检查，不能只看非空的候选列表。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-loading.html">第一次三维装箱</a>，学习从候选选择到最终放置。</li><li>增加箱型、重量和费用，明确目标权重的业务含义。</li><li>综合航空装载可参考<a href="/ospf/zh-cn/examples/framework-example2.html">复杂示例 2</a>，但行业安全规则不因使用 BPP3D 而自动具备。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp3d/README_ch.md" target="_blank" rel="noreferrer">Kotlin 入口与形状支持说明</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp3d/README_ch.md" target="_blank" rel="noreferrer">Rust 入口与领域规则</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./first-loading.html">第一次三维装箱</a>。完成后再学<a href="./business-scenario.html">多箱型与目标配置</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',19)])])}const m=a(o,[["render",i]]);export{f as __pageData,m as default};
